/**
 * Coco Tran — Answerable opening / Content system / Booking box: one-shot ACF import (idempotent).
 *
 * Imports three field groups exactly as ACF → Tools → Import would, skipping any that already exist:
 *   group_ct_answerable_opening  — byline, short answer, five "At a glance" rows (Setting / Best for /
 *                                  Standout / Consider / Stayed), visited, visit basis, updated on,
 *                                  disclosure (Paid / Hosted / Discounted stay …), advisor roundup
 *   group_ct_content_system      — content category, health, goal, keywords, AI questions, last fact check, hub
 *   group_ct_booking_access      — booking access (how it was booked) + perks override, on Properties
 *
 * Run ONE of: Code Snippets (WPCode) → PHP → Run once · wp eval-file eeat-opening-setup.php · php eeat-opening-setup.php beside wp-load.php
 * Afterwards publish the Kadence Element "Answerable opening" (created as a draft over REST, post 30407).
 */
if ( ! defined( 'ABSPATH' ) ) {
	$ct_dir = __DIR__;
	for ( $i = 0; $i < 6; $i++ ) {
		if ( file_exists( $ct_dir . '/wp-load.php' ) ) { require_once $ct_dir . '/wp-load.php'; break; }
		$ct_dir = dirname( $ct_dir );
	}
	if ( ! defined( 'ABSPATH' ) ) { fwrite( STDERR, "wp-load.php not found.\n" ); exit( 1 ); }
}
function ct_eeat_say( $msg ) {
	if ( class_exists( 'WP_CLI' ) ) { WP_CLI::log( $msg ); }
	elseif ( php_sapi_name() === 'cli' ) { echo $msg, "\n"; }
	else { echo esc_html( $msg ), "<br>\n"; }
}
