ct_eeat_say( '== ACF field groups: Answerable opening · Content system · Booking box ==' );
if ( ! function_exists( 'acf_get_field_group' ) ) {
	ct_eeat_say( 'ERROR: ACF is not active on this site. Activate Advanced Custom Fields PRO and run again.' );
	return;
}
$groups = json_decode( ct_eeat_groups_json(), true );
if ( ! is_array( $groups ) ) { ct_eeat_say( 'ERROR: embedded JSON did not decode.' ); return; }
foreach ( $groups as $group ) {
	if ( empty( $group['key'] ) ) { continue; }
	$existing = acf_get_field_group( $group['key'] );
	if ( $existing ) {
		ct_eeat_say( sprintf( 'Found "%s" (%s) already registered — not re-imported.', $existing['title'], $group['key'] ) );
		continue;
	}
	if ( ! function_exists( 'acf_import_field_group' ) ) { ct_eeat_say( 'ERROR: acf_import_field_group() missing (ACF too old).' ); continue; }
	if ( function_exists( 'acf_get_field_group_post' ) ) {
		$post = acf_get_field_group_post( $group['key'] );
		if ( $post ) { $group['ID'] = $post->ID; }
	}
	$imported = acf_import_field_group( $group );
	if ( is_array( $imported ) && ! empty( $imported['ID'] ) ) {
		ct_eeat_say( sprintf( 'Imported "%s" → post ID %d, %d fields.', $imported['title'], $imported['ID'], count( $group['fields'] ) ) );
	} else {
		ct_eeat_say( sprintf( 'ERROR importing %s.', $group['key'] ) );
	}
}
